 stellarTexture(){if(this.stellarDetail)return this.stellarDetail;const size=this.width<600?384:768,c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d'),pixels=ctx.createImageData(size,size);const fract=x=>x-Math.floor(x);const hash=(x,y)=>fract(Math.sin(x*127.1+y*311.7)*43758.5453);const noise=(x,y)=>{const ix=Math.floor(x),iy=Math.floor(y);let fx=fract(x),fy=fract(y);fx=fx*fx*(3-2*fx);fy=fy*fy*(3-2*fy);const a=hash(ix,iy),b=hash(ix+1,iy),d=hash(ix,iy+1),e=hash(ix+1,iy+1);return (a+(b-a)*fx)*(1-fy)+(d+(e-d)*fx)*fy;};for(let y=0;y<size;y++)for(let x=0;x<size;x++){const sx=(x+.5)/size*2-1,sy=(y+.5)/size*2-1,r2=sx*sx+sy*sy;if(r2>=1)continue;const z=Math.sqrt(1-r2),u=Math.atan2(sx,z),v=Math.asin(sy);const coarse=noise(u*9+5,v*9+5),cell=noise(u*100+11,v*100+11),fine=noise(u*245,v*245),spots=Math.max(0,noise(u*13+39,v*13+39)-.63)*2;const value=Math.max(.09,.22+coarse*.44+cell*.3+fine*.13-spots);const i=(y*size+x)*4;pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=value*255;pixels.data[i+3]=Math.min(1,(1-r2)*size/2)*255;}ctx.putImageData(pixels,0,0);this.stellarDetail=c;return c;}
